fun makeCounter(): () -> Int {
    var count = 0
    return { ++count }
}

fun main() {
    val a = makeCounter()
    val b = makeCounter()
    a(); a()
    println("${a()} ${b()}")
}

fun main() {
    val result = listOf(1, 2, 3, 4).map(fun(x: Int): Int {
        if (x % 2 == 0) return 0
        return x * 10
    })
    println(result)
}

var n = 0
fun next(): Int { n++; return n }

fun f(a: Int = next(), b: Int = a * 10) = "$a $b"

fun main() {
    println(f())
    println(f(b = 1))
    println(f())
}
